import{_ as a,c as e,a2 as r,o}from"./chunks/framework.CO0qOYmW.js";const p=JSON.parse('{"title":"知识平台概述","description":"","frontmatter":{},"headers":[],"relativePath":"ai/03-knowledge-platform/01-platform/01-overview.md","filePath":"ai/03-knowledge-platform/01-platform/01-overview.md","lastUpdated":1783608971000}'),d={name:"ai/03-knowledge-platform/01-platform/01-overview.md"};function l(i,t,n,s,h,m){return o(),e("div",null,t[0]||(t[0]=[r('<h1 id="知识平台概述" tabindex="-1">知识平台概述 <a class="header-anchor" href="#知识平台概述" aria-label="Permalink to &quot;知识平台概述&quot;">​</a></h1><p>知识平台是企业 AI 应用的数据底座，负责把文档、业务数据、知识库、工单、制度和历史经验转化为可检索、可治理、可追溯的知识资产。</p><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><ul><li><strong>知识资产化</strong>：把分散的非结构化内容整理成可供 AI 应用使用的知识资源。</li><li><strong>检索可用性</strong>：通过解析、清洗、切分、Embedding 和索引构建提升召回质量。</li><li><strong>企业治理</strong>：处理权限、版本、过期、同步、质量评估和多知识库管理。</li></ul><h2 id="平台能力" tabindex="-1">平台能力 <a class="header-anchor" href="#平台能力" aria-label="Permalink to &quot;平台能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>知识接入</td><td>接入文档、网页、数据库、工单、IM 记录和业务系统数据</td></tr><tr><td>内容处理</td><td>完成解析、清洗、切分、元数据标注和结构化转换</td></tr><tr><td>索引构建</td><td>使用 Embedding、向量库和关键词索引构建检索能力</td></tr><tr><td>治理运维</td><td>管理权限隔离、版本更新、知识过期和质量评估</td></tr></tbody></table><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>先理解企业知识来源和知识平台在 AI 架构中的位置。</li><li>再掌握文档解析、切分、Embedding 和索引构建的关键策略。</li><li>最后关注权限隔离、质量评估和知识更新，保证知识可用且可信。</li></ol>',8)]))}const f=a(d,[["render",l]]);export{p as __pageData,f as default};
